```python
import random

def play_game():
    # Generate a random number between 1 and 100
    random_number = random.randint(1, 100)

    print("I've generated a random number between 1 and 100. Can you guess it?")

    while True:
        user_guess = int(input("Enter your guess: "))

        if user_guess < 1 or user_guess > 100:
            print("Please enter a number between 1 and 100.")
            continue

        break

    print(f"Is your guess higher or lower than {random_number}?")

    user_feedback = input().lower()

    if user_feedback == "higher":
        if user_guess > random_number:
            print("Congratulations! You've guessed correctly.")
        else:
            print("Sorry, your guess is too low. Try again!")
    elif user_feedback == "lower":
        if user_guess < random_number:
            print("Congratulations! You've guessed correctly.")
        else:
            print("Sorry, your guess is too high. Try again!")
    else:
        print("Please enter 'higher' or 'lower'.")

# Play the game
play_game()
```

This code will generate a random number between 1 and 100, prompt the user to guess, and provide feedback based on whether the user's guess is higher or lower than the random number.
